mapper.select:
SELECT 
FROM sys_cache_policy
WHERE tenant_id = #{tenantId}
  AND application_code = #{applicationCode}
  AND cache_name = #{cacheName}
  AND del_flag = 0
LIMIT 1

mapper.update:
UPDATE sys_cache_policy
SET del_flag = id,
    policy_version = policy_version + 1,
    update_by = #{updateBy},
    update_time = #{updateTime}
WHERE tenant_id = #{tenantId}
  AND application_code = #{applicationCode}
  AND cache_name = #{cacheName}
  AND policy_version = #{expectedVersion}
  AND del_flag = 0
